import{_ as i,o as t,c as n,a2 as a}from"./chunks/framework.5akMI7mQ.js";const g=JSON.parse('{"title":"Overview","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/overview.md","filePath":"getting-started/overview.md","lastUpdated":1792429063000}'),s={name:"getting-started/overview.md"};function o(r,e,l,d,c,u){return t(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h1><p><strong>Wednes Serverless Engine</strong> (<code>wednesd</code>) is a high-performance, edge-ready serverless runtime engineered around the WebAssembly (Wasm) Component Model and the Cranelift optimizing JIT compiler.</p><p>Designed for modern cloud workloads, microservices, and AI edge pipelines, it combines sub-millisecond execution with memory density and zero-trust sandboxing.</p><hr><h2 id="key-highlights" tabindex="-1">Key Highlights <a class="header-anchor" href="#key-highlights" aria-label="Permalink to &quot;Key Highlights&quot;">​</a></h2><ul><li><strong>Near-Zero Cold Start:</strong> Microsecond-level instance instantiation powered by pre-instantiated component templates (<code>instantiate_pre</code>).</li><li><strong>Standardized ABI:</strong> Interoperates through the official WIT interface <code>wednes:function@0.1.0</code>.</li><li><strong>Multi-Protocol Gateway:</strong> Integrated HTTP/1.1, HTTP/2, and HTTP/3 (QUIC over UDP) with automated self-signed or production TLS certificates.</li><li><strong>Micro-Sandboxing &amp; Isolation:</strong> Hardened memory budgets (via Wasmtime <code>StoreLimits</code>), deterministic execution timeouts (via epoch-based trapping), and strict isolation preventing unauthorized host filesystem access or socket escape.</li><li><strong>Atomic Registries:</strong> Safe function updates and zero-downtime metadata swaps using transactional tempfile renames.</li><li><strong>Polyglot Developer Experience:</strong> First-class compilation pipelines for Rust, TypeScript/JavaScript, and Python.</li></ul><hr><h2 id="when-to-use-wednes-serverless-engine" tabindex="-1">When to Use Wednes Serverless Engine <a class="header-anchor" href="#when-to-use-wednes-serverless-engine" aria-label="Permalink to &quot;When to Use Wednes Serverless Engine&quot;">​</a></h2><p>Wednes Serverless Engine excels in scenarios where traditional container-based systems (like Docker, Kubernetes Pods, or Knative) introduce excessive resource overhead and latency:</p><ol><li><strong>High-Density Webhooks &amp; Event Processing:</strong> Running hundreds or thousands of distinct client endpoints on a single small node (e.g., 2 GB RAM) without running out of memory.</li><li><strong>Ultra-Low Latency APIs:</strong> Handling authentication dispatchers, JWT verifications, edge transformers, or data filtering with sub-millisecond response guarantees.</li><li><strong>Multi-Tenant Plugin Systems:</strong> Securely executing third-party or untrusted business logic without risking host compromise.</li><li><strong>Edge &amp; IoT Micro-Gateways:</strong> Deploying lightweight services to resource-constrained cloud servers or edge devices with full HTTP/3 QUIC connectivity.</li></ol><hr><h2 id="design-principles" tabindex="-1">Design Principles <a class="header-anchor" href="#design-principles" aria-label="Permalink to &quot;Design Principles&quot;">​</a></h2><h3 id="_1-minimal-footprint-maximum-density" tabindex="-1">1. Minimal Footprint, Maximum Density <a class="header-anchor" href="#_1-minimal-footprint-maximum-density" aria-label="Permalink to &quot;1. Minimal Footprint, Maximum Density&quot;">​</a></h3><p>Rather than booting a Linux kernel or isolated guest OS for every workload, Wednes uses lightweight WebAssembly instances. Ten active functions consume as little as <strong>20.33 MiB</strong> of idle RSS memory.</p><h3 id="_2-zero-trust-sandboxing" tabindex="-1">2. Zero-Trust Sandboxing <a class="header-anchor" href="#_2-zero-trust-sandboxing" aria-label="Permalink to &quot;2. Zero-Trust Sandboxing&quot;">​</a></h3><p>By default, functions run in a closed world:</p><ul><li>No ambient environment variables.</li><li>No direct host filesystem preopens.</li><li>No outbound socket creation unless explicitly authorized.</li><li>Strictly enforced CPU and memory limits per invocation.</li></ul><h3 id="_3-native-cloud-native-standards" tabindex="-1">3. Native Cloud-Native Standards <a class="header-anchor" href="#_3-native-cloud-native-standards" aria-label="Permalink to &quot;3. Native Cloud-Native Standards&quot;">​</a></h3><p>Wednes adheres to CNCF and bytecode alliance standards, including:</p><ul><li>WebAssembly System Interface (WASI).</li><li>WebAssembly Component Model (<code>wit</code>).</li><li>Standard Prometheus/JSON telemetry.</li><li>Open Container and systemd packaging.</li></ul><hr><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><ul><li>Jump straight into building your first function in the <a href="./quickstart">Quickstart Guide</a>.</li><li>Explore runtime internals in the <a href="./architecture">Architecture Specification</a>.</li><li>Inspect the <a href="./../core-concepts/wednes-yaml">wednes.yaml Specification</a>.</li></ul>',23)])])}const m=i(s,[["render",o]]);export{g as __pageData,m as default};
